#!/usr/bin/env python3
"""sen0401_lineage_res32 v1_0_0 - change route (G113, G125 route 2, G133, G147) for the owner's answer of 2026-11-01 to the sheet question: 'Sheet stays PDF' = paper and key in Word (.docx), the answer sheet a position-exact PDF; so 4 pages = 3 paper pages (Word) + 1 sheet page (PDF), and the paper must fit 3 pages. Amends the rewrite of v0.730 (res31). A StageRevision from the Backlog stage; the not-started story ST_Repair_Exam_Paper and its two tasks and criterion are REWRITTEN (nothing is started), no committed file is edited. Events: change | retract | backlog PREV | fill PREV"""
__version__ = "1.0.0"
import os, re, sys, glob, importlib.util
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sen0401_lineage_succession_v1_1_0 as M
import sen0401_lineage_succession3_v1_1_0 as X
