import sen0401_lineage_retro24_v1_0_0 as RT
R = RT.R; lit = G.lit
def _pv_newest():
    fw = X.FW; vk = lambda q: [int(x) for x in re.findall(r"_v(\d+)_(\d+)_(\d+)\.", q)[0]]
    spec = importlib.util.spec_from_file_location("pv", sorted(glob.glob(fw + "/03-tooling/backlog_pipeline_verify_v*.py"), key=vk)[-1])
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    m.STAGE_TYPES = m._load_stage_types(sorted(glob.glob(fw + "/01-ontologies/backlog_tbox_v*.ttl"), key=vk)[-1], table="v4")
    return m
X._pv = _pv_newest

REV = "ex:Revision_Lineage3_Backlog12"; OLD = "ex:Out3_BacklogR39"; NEWB = "ex:Out3_BacklogR40"; R.NEWB = NEWB
CR = "ex:CR3_PaperSheetPdf"; IA = "ex:IA3_PaperSheetPdf"; SID = "ST_Repair_Exam_Paper"
WHEN = "Sunday 2026-11-01, on the owner's answer 'Sheet stays PDF' relayed by the coordinator (to the sheet question after his words of 11:52)"
WORDS = ("THE OWNER'S ANSWER: 'Sheet stays PDF' = paper and key in Word (.docx), the answer sheet a position-exact PDF (safest for scanning); four pages in total = 3 paper pages (Word) + 1 sheet page (PDF), printed double sided on 2 sheets, so the paper must fit 3 pages. THE OWNER'S WORDS (relayed, 2026-11-01 and the day before): 'I need the PPT slides and interactive HTML files for both courses. Midterm scope: SEN0401: Chapters 1-6 ... the MS Word midterm exams, answer sheets. I will give you some details about the exam questions, as I made some interactive sessions during the class and ask them questions to understand if the students are reached to a certain level. The examinations should be developed to fit into 4 pages in total, to print in 2 pages, easy to read and assess, but using various techniques, including calculations, ordering, etc, that can be helpful to replace hand writing answers.' Earlier: '4 Pages to fit into 2 pages double side print. Mixed order mixed questions.' and 'Not PDF, MS Explorer for edit option'.")
MEAS = ("MEASURED 2026-11-01 by the lineage agent on the committed items (23 items, 24 units) and renderer v1.2.0: the paper alone fills 4.2 to 4.4 content pages at the committed settings; with every layout lever together (margin 10 mm, leading 1.12, code 8 pt, item gap 1.0 mm, column gap 6 mm; text stays at 10 pt) it still fills 3.31 (chapter order) and 3.47 (grouped by type) content pages, i.e. 4 pages. So 3 content pages plus 1 answer-sheet page is NOT reachable by layout alone: the items must be shorter or fewer (about 10 to 15 percent less text), or the answer sheet must share a page with the last paper page. The paper rules (R01 text at least 10 pt, code at least 8 pt; R17 columns; R10 code capacity) are not changed.")
FACT = WORDS + " " + MEAS
TITLE = "REPAIR: the midterm paper v2 - 3 paper pages in MS Word (.docx) plus 1 answer-sheet page in PDF (4 pages on 2 sheets), seeded mixed order, a form code per form, a code box wide enough"
AC_LABEL = "The midterm paper v2 is 3 Word pages plus a 1-page PDF answer sheet, mixed order, with a form code per form and a code box wide enough"
TXT_B = ("Make the NEW midterm paper v2 as new files (08-tooling/exam; v1.0.0 files, the renderers v1.1/v1.2 and the items v1.0.0 are never edited, SHA-256 before and after). INPUTS: " + WORDS + " THE ITEMS STAY SEEDS: the owner will send the question styles of his class sessions through the coordinator; until the lineage agent passes them to you, build with the items v1.0.0 as they are, shortened only as (1) allows (and STOP and report instead of inventing an item style); a changed or shorter item is a NEW items version (never an edit). "
         "(1) PAGES: the PAPER (questions) is 3 pages in MS Word, the ANSWER SHEET is 1 page, PDF, 4 pages in total, printed double sided on 2 sheets. " + MEAS + " Because the sheet is its own page, the paper must reach 3 content pages: about 10 to 15 percent less item text on top of the tightest layout the paper rules allow. Do it as a NEW items version with shorter listings and option texts, ONLY where the engine and its refusals allow (run the engine on the new file; an item it refuses stays as it was), every item keeping its chapter, Bloom level, answer and computed value; REPORT EACH ITEM CHANGED with the before and after text and the characters saved, and the measured pages. No paper rule is lowered (R01 text 10 pt, code 8 pt; R17; R10). If 3 pages are not reached within the rules, STOP and report the measurements. "
         "(2) THE cs_encode ITEM (mt1:i20:trace-compactsize) uses cs_encode without defining it. The lineage agent's decision from the chapter's own facts (CompactSize, Mastering Bitcoin ch. 6, slide 20 of the chapter deck): define it INSIDE the item in one short line of the question as the standard sizes: a count below 253 takes 1 byte, up to 65535 takes 3 bytes, up to 4294967295 takes 5 bytes, anything larger takes 9 bytes; the code, the output 14 and the computed value stay; check the answer 14 by running a real implementation in your control. If the item cannot hold the line within its code-capacity rule, replace the code by a defined function of the same idea and report it. "
         "(3) MIXED ORDER: the 24 units in a seeded mixed order (chapters and question types mixed), one rule: a permutation drawn from a recorded seed, with the stated constraints (no two consecutive units of the same item; first unit of low difficulty); the number of forms is a PARAMETER with the default 2 (forms A and B with different seeds, to deter copying), a default and NOT the owner's decision; each form has its own form code (a stated rule, valid for the sheet's check digit if there is one), printed on its paper, sheet, layout and key, and the grading tool's pair check refuses a mismatch. "
         "(4) MS WORD, PAPER AND KEY ONLY: the paper and the key are .docx files that open and edit in Word, with a PDF export of each for printing. Word is not available here, LibreOffice is: the page count (3 paper pages) is VERIFIED on the LibreOffice render of the .docx; build it so the count has margin (a safety of at least 3 percent of a page, since Word may break lines differently): fixed widths, named fonts with metric-compatible fallbacks, explicit column breaks if the paper uses columns, no dependence on automatic spacing. Say in your report what Word may still shift (fonts, line breaks, hyphenation, table padding). "
         "(5) THE ANSWER SHEET stays a position-exact PDF made by the sheet renderer of the repository (the reader reads its layout JSON): one page, a form code per form, the code box and the layout as before; the sheet is NOT made in Word. VERIFY the sheet as the reader v1.1.0 (v1.2.0 when committed) reads it: the synthetic sheets of the layout read with the registration tolerance, as in the papers control. "
         "(6) CODE BOX at least as wide as the longest allowed line (45 characters) at the printed size, in a NEW renderer version, every code box measured. "
         "(7) The FINAL build of the paper and sheet waits for the reader v1.2.0 (task TK_Repair_Exam_Reader_Build, running now): check git log for it before the last step; the renderer, the .docx writer and the page budget do not wait. If it is not committed, deliver the build with the reader v1.1.0 named as the reader of record, and say so. "
         "Run the control's own scripts (sen0401_exam_papers_control_check_v1_0_0.py, adapted as a new file). DO NOT EDIT OR APPEND TO ANY FILE COMMITTED EARLIER, INCLUDING YOUR OWN LOG FILES. Commit ONLY your own files to main (git add by path, pull --rebase before push); commit each verified step at once. Report every result as printed. Planned session SEN0401-I54-paperfix; about 5.0 hours (an estimate, G120).")
TXT_V = "Open each .docx and PDF and read every page; render the paper .docx myself with LibreOffice and count the pages (paper 3 plus sheet 1 = 4); read every changed item against the old text and the key; run a real cs_encode against the answer; read the sheet PDF with the reader of record on my own synthetic sheets with shifts, scales and rotations; run the papers control script; compare the form codes of the forms and the pair check of the grading tool; nochange (SHA-256 of every earlier file)."
AC_G = ("Owner-directed work (" + CR + ", " + WHEN + "). Given the committed items v1.0.0, renderer v1.2.0 and the owner's answer, when the NEW paper v2 is made, then ALL of: (1) every file is new and no committed file is edited; (2) the paper (.docx) is exactly 3 pages on the LibreOffice render with a margin of at least 3 percent of a page, the answer sheet is exactly 1 page (PDF), 4 pages in total printable double sided on 2 sheets, text at least 10 pt and code at least 8 pt on the render; (3) the paper and the key are .docx files that open in Word, with PDF exports; (4) the 24 units are in a seeded mixed order by a stated rule, the number of forms is a parameter (default 2, not the owner's decision), each form has a distinct form code carried by its paper, sheet, layout and key; (5) item shortening is a new items version, every item changed is reported with before and after, chapter, Bloom level, answer and computed value unchanged, and the cs_encode item defines the CompactSize sizes inside the item with the answer 14 checked on a real implementation; (6) the sheet PDF is read by the reader of record on synthetic sheets of its layout with 0 silent wrong; (7) no line of a code box is wider than its box, measured for every item; (8) the papers control script passes (key against the items). The items stay seeds until the owner's question styles are passed; no item style is invented. Results as printed; if any element fails the work is named failing, and a rule is never changed to pass. " + FACT)
def sub_attr(b, pred, val):
    pat = re.compile(r'(%s )"(?:[^"\\]|\\.)*"(@en)?' % re.escape(pred)); m = pat.search(b); assert m, pred
    return b[:m.start()] + m.group(1) + lit(val) + (m.group(2) or "") + b[m.end():]
def edit_blk(t, sid, fn):
    i, j = T.blk(t, sid); return t[:i] + fn(t[i:j]) + t[j:]
def ev_change(t):
    cr = ('\n%s a backlog:ChangeRequest ;\n    rdfs:label "The midterm paper is 3 Word pages plus a 1-page PDF answer sheet, mixed order"@en ;\n    backlog:requestsChangeTo ex:Scope3 ; backlog:hasChangeDirection backlog:Direction_Grow ; backlog:hasDisposition backlog:Disp_Pending ; rdfs:seeAlso %s, ex:CR3_ExamMission, ex:CR3_PaperFormCode, ex:CR3_PaperWordFourPages ;\n    backlog:hasChangeRequestRationale %s .\n') % (CR, IA, lit("Raised " + WHEN + ". " + FACT))
    ia = ('\n%s a backlog:ImpactAssessment ;\n    rdfs:label "What the 3 Word pages plus 1 PDF sheet page cost and touch"@en ;\n    backlog:analyzesRequest %s ; backlog:identifiesAffectedLineage ex:Lineage3 ;\n    backlog:hasImpactStatement %s .\n') % (IA, CR, lit(FACT + " AFFECTED: the not-started story ST_Repair_Exam_Paper and its two tasks and criterion are rewritten again (G133: nothing is started; it supersedes the rewrite of v0.730, which asked for a Word sheet); the owner chose the PDF sheet, the safest for scanning, so the Word-sheet verification falls away and the page budget becomes 3 paper pages. The paper's page count in Word cannot be proven here: it is measured on the LibreOffice render with a margin. The cs_encode item is decided from the chapter's facts (defined inside the item), not by the owner. The items stay seeds until the owner passes the question styles of his class sessions; the reader repair (ST_Repair_Exam_Reader, unchanged) must be committed before the final build of the paper. NOT AFFECTED: every committed file, the grading tool, the reader story. OPEN FOR THE OWNER: whether the answer sheet may share a page with the paper, whether a second form with another mix is wanted, the cs_encode definition, the 24 items, the default of 6 at Analyze+, and the question styles. ESTIMATE (G120): 5 h build, 1.5 h verification (unchanged from v0.730)."))
    return t + cr + ia, "Change request with impact assessment: the owner's words of 2026-11-01 on the midterm paper (4 pages in total, mixed order, paper, key and answer sheet in MS Word, question styles to follow); no stage changed."
def ev_retract(t):
    reason = ("The change request " + CR + " (" + WHEN + ") rewrites the criterion, the story and the two tasks of ST_Repair_Exam_Paper, none of them started; a changed criterion is counted by the Backlog digest, so the Backlog stage is revised (G125 route 2): this version retracts the Backlog output " + OLD + " and rebuilds nothing; the next version rebuilds it and a third fills the last commit.")
    b = ('\n%s a backlog:StageRevision ;\n    rdfs:label "Revision of the third lineage from the Backlog stage: the midterm paper in 3 Word pages plus a PDF answer sheet"@en ;\n    backlog:revisesLineage ex:Lineage3 ; backlog:revisesFromStage backlog:Stage_Backlog ;\n'
         '    rdfs:seeAlso %s, %s ;\n    backlog:revisionReason %s ;\n    backlog:retractsOutput %s ; backlog:decidedBy backlog:Builder ;\n    backlog:revisedAtCommit "PENDING" .\n%s backlog:outputRetracted true .\n') % (REV, CR, IA, lit(reason), OLD, OLD)
    return X.set_status(t, "LS_Objectived") + b, "StageRevision of the third lineage from the Backlog stage (G125 route 2): the Backlog output %s is retracted for the owner's words on the midterm paper; nothing is rebuilt here." % OLD.replace("ex:", "")
def ev_backlog(t, prev):
    t = re.sub(r'(%s a backlog:StageRevision.*?backlog:revisedAtCommit )"PENDING"' % re.escape(REV), lambda m: m.group(1) + '"%s"' % prev, t, count=1, flags=re.S)
    t = X.set_status(t, "LS_Backlogged"); now = M.now()
    n = t.count("backlog:admittedByOutput %s ;" % OLD); assert n >= 40, n
    t = t.replace("backlog:admittedByOutput %s ;" % OLD, "backlog:admittedByOutput %s ;" % NEWB)
    # rewrite the not-started items (G133); states are checked
    for x in (SID, "TK_Repair_Exam_Paper_Build", "TK_Repair_Exam_Paper_Verify", "AC3E_Repair_PaperFormCode"):
        i, j = T.blk(t, x); assert ("backlog:Ready" in t[i:j] or "backlog:Proposed" in t[i:j]) or x.startswith("AC3E"), x
    def f_story(b):
        b = sub_attr(b, "rdfs:label", TITLE); b = sub_attr(b, "backlog:hasTitle", TITLE)
        b = sub_attr(b, "backlog:wantsCapability", TITLE)
        b = sub_attr(b, "backlog:hasAuditNote", "Admitted Friday 2026-10-30 and REWRITTEN AGAIN " + WHEN + " (" + CR + ", ex:CR3_PaperWordFourPages, ex:CR3_PaperFormCode); nothing was started (G133). One criterion per unit.")
        return b
    t = edit_blk(t, SID, f_story)
    t = edit_blk(t, "TK_Repair_Exam_Paper_Build", lambda b: sub_attr(sub_attr(sub_attr(b, "rdfs:label", "Build: " + TITLE), "backlog:hasTitle", "Build: " + TITLE), "backlog:hasAuditNote", TXT_B))
    t = edit_blk(t, "TK_Repair_Exam_Paper_Verify", lambda b: sub_attr(sub_attr(sub_attr(b, "rdfs:label", "Verify: " + TITLE), "backlog:hasTitle", "Verify: " + TITLE), "backlog:hasAuditNote", TXT_V))
    def f_ac(b):
        b = sub_attr(b, "rdfs:label", AC_LABEL); b = sub_attr(b, "backlog:hasGherkinText", AC_G)
        return sub_attr(b, "backlog:measuredWithVersion", "papers control script (adapted new file); LibreOffice render of the paper .docx; reader on the sheet PDF")
    t = edit_blk(t, "AC3E_Repair_PaperFormCode", f_ac)
    L = []
    mem = []
    L.append('ex:SC3_ExamSheetPdf a backlog:ScopeChange ;\n    rdfs:label "Backlog rewritten for the 3 Word pages plus PDF sheet midterm paper"@en ;\n    backlog:fulfillsRequest %s ; backlog:changesScope ex:Scope3 ; backlog:decidedBy backlog:Builder ;\n    backlog:admitsItem ex:%s ;\n    backlog:hasScopeChangeRationale %s .\n' % (CR, SID, lit("The owner's words of 2026-11-01; the story, its criterion and its two tasks are rewritten while not started (G133); the rule that a change re-ranks the open items. " + FACT)))
    t, kk = re.subn(r'(%s a backlog:ChangeRequest ;.*?backlog:hasDisposition )backlog:Disp_Pending' % re.escape(CR), lambda m: m.group(1) + "backlog:Disp_Accepted", t, count=1, flags=re.S); assert kk == 1
    L.append('%s rdfs:comment "Disposition set to Accepted on %s in the version that records the ScopeChange ex:SC3_ExamSheetPdf; it was Pending before."@en .\n' % (CR, now[:10]))
    t += "\n" + "".join(L)
    return t + ('\nex:Out3_BacklogR40 a backlog:StageOutput ;\n    rdfs:label "Closure of the Backlog stage of the third lineage, rebuilt for the 3 Word pages plus PDF sheet midterm paper"@en ;\n    backlog:belongsToLineage ex:Lineage3 ;\n'
                '    backlog:outputOfStage backlog:Stage_Backlog ;\n    backlog:consumesOutput ex:Out3_ObjectiveR32 ;\n    backlog:hasStateDigest "%s" ;\n    backlog:closedAtCommit "PENDING" .\n') % X.digest(t, "Backlog"), \
        "third lineage, Backlog stage rebuilt: ST_Repair_Exam_Paper rewritten again for the owner's answer: 3 Word paper pages plus a PDF sheet page (change request Accepted); %d items re-admitted." % n
def ev_fill(t, prev): return G.fill_re(t, NEWB, prev), "closedAtCommit of the rebuilt Backlog output %s set to the commit that closed it (%s)." % (NEWB.replace("ex:", ""), prev)
def main():
    ev = sys.argv[1]; src = M.newest(); t = open(src, encoding="utf-8").read(); nxt, cur = M.next_version(src)
    fn = {"change": lambda: ev_change(t), "retract": lambda: ev_retract(t), "backlog": lambda: ev_backlog(t, sys.argv[2]), "fill": lambda: ev_fill(t, sys.argv[2])}
    nt, comment = fn[ev](); print(os.path.basename(M.write_new(src, nt, nxt, cur, comment)))
if __name__ == "__main__": main()
